import{_ as e,o,c as d,ah as n}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Document types","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/gestion-documentaire/types-de-documents.md","filePath":"src/en/guide/gestion-documentaire/types-de-documents.md"}'),a={name:"en/guide/gestion-documentaire/types-de-documents.md"};function r(i,t,s,c,l,h){return o(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="document-types" tabindex="-1">Document types <a class="header-anchor" href="#document-types" aria-label="Permalink to &quot;Document types&quot;">​</a></h1><p>The <strong>Document types</strong> catalogue describes the documents the school files: which file each goes in, who consults it, who validates it, whether it is confidential and how long it is kept. An administrator or the document manager keeps it, from the <strong>Documents</strong> space → <strong>Document types</strong>.</p><h2 id="the-starting-catalogue" tabindex="-1">The starting catalogue <a class="header-anchor" href="#the-starting-catalogue" aria-label="Permalink to &quot;The starting catalogue&quot;">​</a></h2><p>ERA starts with the usual list, which you adapt freely:</p><table tabindex="0"><thead><tr><th>Type</th><th>File</th><th>Origin</th><th>Consults and validates</th></tr></thead><tbody><tr><td>Enrollment file</td><td>Student</td><td>Imported</td><td>Document manager, office</td></tr><tr><td>Birth certificate</td><td>Student</td><td>Imported</td><td>Document manager, office</td></tr><tr><td>Medical record</td><td>Student</td><td>Imported (confidential)</td><td>Infirmary</td></tr><tr><td>Application file</td><td>Student</td><td>Imported</td><td>Document manager, office</td></tr><tr><td>Transcript</td><td>Student</td><td>Produced by the school</td><td>Document manager, office</td></tr><tr><td>Certificate</td><td>Student</td><td>Produced by the school</td><td>Document manager, office</td></tr><tr><td>Diploma</td><td>Student</td><td>Produced by the school</td><td>Document manager, office</td></tr><tr><td>Internship agreement</td><td>Student</td><td>Produced by the school</td><td>Document manager, office</td></tr><tr><td>Invoice or receipt</td><td>Student</td><td>Produced by the school</td><td>Document manager, office; the cashier consults</td></tr><tr><td>Employment contract</td><td>Employee</td><td>Imported (confidential)</td><td>Document manager</td></tr><tr><td>Minutes</td><td>School</td><td>Produced by the school</td><td>Document manager, office</td></tr></tbody></table><p>An administrator always consults and validates every type, confidential ones included. The starting names show in each user&#39;s language until you rename them.</p><h2 id="create-or-edit-a-type" tabindex="-1">Create or edit a type <a class="header-anchor" href="#create-or-edit-a-type" aria-label="Permalink to &quot;Create or edit a type&quot;">​</a></h2><ol><li>Click <strong>New type</strong>, or <strong>Edit</strong> on a type&#39;s row.</li><li>Fill in the <strong>Name</strong>.</li><li>Choose the <strong>File</strong>: the student&#39;s, the employee&#39;s, or the school&#39;s documents. Once documents are filed under a type, its file can no longer change.</li><li>Choose the <strong>Origin</strong>: <strong>Imported</strong> for a document handed in by a family or an employee, <strong>Produced by the school</strong> for a document it issues.</li><li>Enter the <strong>Retention period</strong> in years, or leave it empty to keep it without limit.</li><li>Tick <strong>Confidential document</strong> so that every consultation is recorded in the activity log.</li><li>Under <strong>Access</strong>, tick for each profile whether it <strong>consults and files</strong> this type, and whether it <strong>validates</strong> it. Whoever validates a type necessarily consults it too: the first box ticks itself.</li><li>Click <strong>Save</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Reserving a type for administrators</p><p>To reserve a type for the school&#39;s leadership, tick no profile: only administrators will have access to it.</p></div><h2 id="delete-a-type" tabindex="-1">Delete a type <a class="header-anchor" href="#delete-a-type" aria-label="Permalink to &quot;Delete a type&quot;">​</a></h2><p>A type with no document filed under it can be deleted with <strong>Delete</strong>. As soon as a document is filed there, the button disappears: the type stays in the catalogue, and you can only rename it or change its access.</p>',11)])])}const p=e(a,[["render",r]]);export{m as __pageData,p as default};
